fn solve(x: i32) -> i32 {
    // Convert the number to a string to determine its length (k)
    // and its repeated digit (d).
    let s = x.to_string();
    let k = s.len() as i32;
    // All characters in s are the same, so we can take the first one.
    let d = s.chars().next().unwrap().to_digit(10).unwrap() as i32;

    // For each digit less than d (i.e., 1 to d-1), we have four "boring" numbers:
    // lengths 1, 2, 3, and 4, costing 1+2+3+4 = 10 presses each.
    // Then for digit d, we only go up to length k, costing 1+2+...+k = k*(k+1)/2.
    (d - 1) * 10 + k * (k + 1) / 2
}

