        // x = 1 -> only "1" -> 1 press
        assert_eq!(solve(1), 1);
        // x = 22 -> all of digit 1 (10 presses) + "2" (1) + "22" (2) = 13
        assert_eq!(solve(22), 13);
        // x = 9999 -> 9 digits * 10 presses each = 90
        assert_eq!(solve(9999), 90);
        // x = 555 -> digits 1-4: 4*10 = 40, plus for 5: lengths 1+2+3 = 6 -> 46
        assert_eq!(solve(555), 46);
